mapper.select:
SELECT bc.*, b.title AS book_title
FROM book_copy bc
LEFT JOIN book b ON b.id = bc.book_id

    AND bc.id=#{query.id}
    AND bc.book_id=#{query.bookId}
    AND bc.barcode LIKE CONCAT('%',#{query.barcode},'%')
    AND bc.call_number LIKE CONCAT('%',#{query.callNumber},'%')
    AND bc.location LIKE CONCAT('%',#{query.location},'%')
    AND bc.status=#{query.status}
    AND bc.acquired_at=#{query.acquiredAt}
    AND bc.price=#{query.price}
    AND bc.condition_note LIKE CONCAT('%',#{query.conditionNote},'%')
    AND bc.version=#{query.version}
    AND bc.created_at=#{query.createdAt}
    AND bc.updated_at=#{query.updatedAt}

ORDER BY bc.id DESC
